const text = $('Telegram Trigger').item.json.message.text || '';
const chatId = $('Telegram Trigger').item.json.message.chat.id;
const messageId = $('Telegram Trigger').item.json.message.message_id;

// 1. Verificar sesión en el backend
let session = { vinculado: false };
try {
  const sessionRes = await fetch('http://host.docker.internal:3000/api/telegram/usuario/' + chatId);
  if (sessionRes.ok) {
    session = await sessionRes.json();
  }
} catch (e) {
  console.error('Error al conectar con el backend de sesiones:', e);
}

let replyText = '';
const words = text.trim().split(/\s+/);
const command = words[0].toLowerCase();
const args = words.slice(1);

if (!session.vinculado) {
  // ==========================================
  // CASO: USUARIO NO AUTENTICADO
  // ==========================================
  if (command === '/login') {
    const username = args[0];
    const password = args[1];
    if (!username || !password) {
      replyText = '⚠️ Uso: `/login <usuario> <contraseña>`\n*(Ejemplo: `/login carlos carlos123`)*';
    } else {
      try {
        const res = await fetch('http://host.docker.internal:3000/api/telegram/vincular', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ username, password, telegramChatId: chatId })
        });
        const data = await res.json();
        if (res.ok) {
          replyText = '🔑 ¡Sesión iniciada con éxito!\n\n👤 **Usuario:** ' + data.username + '\n💼 **Rol:** ' + data.role + '\n👷 **Nombre:** ' + data.employeeName;
        } else {
          replyText = '❌ Error al vincular cuenta: ' + (data.error || 'Credenciales incorrectas.');
        }
      } catch (err) {
        replyText = '❌ Error de conexión con el servidor de base de datos.';
      }
    }
  } else if (command === '/register') {
    const username = args[0];
    const password = args[1];
    const email = args[2];
    const role = args[3];
    if (!username || !password || !role) {
      replyText = '📝 Uso: `/register <usuario> <contraseña> <email_o_guion> <rol>`\n*(Ejemplo: `/register pepe pepe123 pepe@mail.com Operario`)*\n\nRoles válidos: `Admin`, `Vendedor`, `Operario`.';
    } else {
      try {
        const res = await fetch('http://host.docker.internal:3000/api/telegram/registrar', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            username,
            password,
            email: email === '-' ? null : email,
            roleName: role,
            telegramChatId: chatId
          })
        });
        const data = await res.json();
        if (res.ok) {
          replyText = '📝 ¡Usuario registrado y vinculado con éxito!\n\n👤 **Usuario:** ' + data.username + '\n💼 **Rol:** ' + data.role + '\n¡Bienvenido al sistema!';
        } else {
          replyText = '❌ Error de registro: ' + (data.error || 'Error al crear la cuenta.');
        }
      } catch (err) {
        replyText = '❌ Error al contactar con el backend de registro.';
      }
    }
  } else {
    replyText = '👋 ¡Hola! Aún no has vinculado tu cuenta de Telegram al sistema de repuestos Antigravity Motors.\n\nPor favor, usa uno de los siguientes comandos para iniciar sesión o registrarte:\n\n🔑 `/login <usuario> <contraseña>`\n📝 `/register <usuario> <contraseña> <email> <rol>`\n\n*(Ejemplo: `/login carlos carlos123`)*\n*(Roles válidos: Admin, Vendedor, Operario)*';
  }
} else {
  // ==========================================
  // CASO: USUARIO AUTENTICADO
  // ==========================================
  if (command.startsWith('/')) {
    // --- Comando estructurado ---
    if (command === '/logout') {
      try {
        const res = await fetch('http://host.docker.internal:3000/api/telegram/desvincular', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ telegramChatId: chatId })
        });
        replyText = '🔓 Sesión desvinculada de Telegram con éxito. Si deseas volver a operar, usa /login.';
      } catch (err) {
        replyText = '❌ Error al desvincular la sesión en el servidor.';
      }
    } else if (command === '/perfil') {
      replyText = '👤 **Perfil Vinculado:**\n\n👤 **Usuario:** ' + session.username + '\n💼 **Rol:** ' + session.role + '\n👷 **Asociado:** ' + session.employeeName;
    } else if (command === '/stock') {
      const query = args.join(' ');
      if (!query) {
        replyText = '🔎 Uso: `/stock <término>`\n*(Ejemplo: `/stock bujía` o `/stock 13101-0C`)*';
      } else {
        try {
          const res = await fetch('http://host.docker.internal:3000/api/inventario/stock-query?q=' + encodeURIComponent(query));
          const data = await res.json();
          if (data.repuestos && data.repuestos.length > 0) {
            const list = data.repuestos.map(r => 
              '▫️ **[' + r.oem + '] ' + r.nombre + '**\n   └ Marca: *' + r.marca + '* | Cat: *' + r.categoria + '*\n   └ Stock: **' + r.stock + '** (mín: ' + r.stockMinimo + ') - **' + r.estadoStock + '**\n   └ Ubic: *' + r.ubicacion + '*\n   └ Precio: **' + r.precio + ' Bs.**'
            ).join('\n\n');
            replyText = '🔎 **Repuestos encontrados (' + data.repuestos.length + '):**\n\n' + list;
          } else {
            replyText = '❌ No se encontraron repuestos para la búsqueda: "' + query + '"';
          }
        } catch (err) {
          replyText = '❌ Error de conexión al consultar el stock del inventario.';
        }
      }
    } else if (command === '/alertas') {
      try {
        const res = await fetch('http://host.docker.internal:3000/api/telegram/alertas-stock');
        const data = await res.json();
        if (data && data.length > 0) {
          const list = data.map(r => 
            '⚠️ **[' + r.oem + '] ' + r.name + '**\n   └ Stock: **' + r.stock + '** (mínimo: ' + r.minStock + ')\n   └ Ubicación: *' + r.location + '*'
          ).join('\n\n');
          replyText = '⚠️ **Alertas de Stock Crítico (' + data.length + '):**\n\n' + list;
        } else {
          replyText = '✅ ¡Todo en orden! No hay repuestos por debajo del stock mínimo.';
        }
      } catch (err) {
        replyText = '❌ Error al consultar las alertas en el servidor.';
      }
    } else if (command === '/compras') {
      try {
        const res = await fetch('http://host.docker.internal:3000/api/telegram/compras-pendientes');
        const data = await res.json();
        if (data && data.length > 0) {
          const list = data.map(c => 
            '📦 **Pedido #' + c.id + '**\n   └ Proveedor: *' + c.providerName + '*\n   └ Total: **' + c.total + ' Bs.** | Ref: *' + c.nroReferencia + '*\n   └ Acciones: Recibir con `/recibir ' + c.id + '`'
          ).join('\n\n');
          replyText = '📦 **Pedidos de Compra Pendientes (' + data.length + '):**\n\n' + list;
        } else {
          replyText = '✅ No hay pedidos de compras pendientes en este momento.';
        }
      } catch (err) {
        replyText = '❌ Error al obtener las compras pendientes del servidor.';
      }
    } else if (command === '/recibir') {
      const purchaseId = args[0];
      if (!purchaseId) {
        replyText = '📦 Uso: `/recibir <id_pedido>`\n*(Ejemplo: `/recibir 3`)*';
      } else {
        try {
          const res = await fetch('http://host.docker.internal:3000/api/compras/' + purchaseId + '/estado', {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status: 'Recibido', username: session.username })
          });
          const data = await res.json();
          if (res.ok) {
            replyText = '✅ **¡Pedido #' + purchaseId + ' Recibido!**\n\nLa mercadería física ha sido registrada en el Kardex e ingresada al stock de inventario correctamente.';
          } else {
            replyText = '❌ Error al recibir pedido: ' + (data.error || 'No se pudo actualizar el estado.');
          }
        } catch (err) {
          replyText = '❌ Error al procesar la recepción en el servidor.';
        }
      }
    } else {
      replyText = 'ℹ️ **Comandos disponibles:**\n\n🔎 `/stock <búsqueda>` - Buscar repuestos\n⚠️ `/alertas` - Stock por debajo del mínimo\n📦 `/compras` - Pedidos pendientes de recibir\n✅ `/recibir <id>` - Recibir pedido físico\n👤 `/perfil` - Datos de tu cuenta\n🔓 `/logout` - Cerrar sesión';
    }
  } else {
    // --- Lenguaje natural (Llamar al Router de n8n) ---
    try {
      const routerRes = await fetch('http://localhost:5678/webhook/repuestos-router', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chatInput: text,
          sessionId: 'telegram-' + chatId
        })
      });
      const routerData = await routerRes.json();
      replyText = routerData.output || routerData.response || 'No pude obtener respuesta del orquestador inteligente.';
    } catch (e) {
      console.error(e);
      replyText = '⚙️ (Ollama está procesando tu mensaje libre) ...\n\nNo se pudo conectar al orquestador inteligente, pero puedes operar usando los comandos estructurados.';
    }
  }
}

return [{ json: { output: replyText, chatId } }];
